package obfs

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

// These vectors were calculated from the independent reference C# algorithm,
// not generated by this Go implementation. The derivation script is retained.
func TestReferenceChainSizeVectors(t *testing.T) {
	var cases []struct {
		Mode       string  `json:"mode"`
		Key        string  `json:"key_hex"`
		TimeBucket int64   `json:"time_bucket"`
		Lists      [][]int `json:"lists"`
	}
	data, err := os.ReadFile("testdata/reference_chain_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(data, &cases); err != nil {
		t.Fatal(err)
	}
	for _, tc := range cases {
		p, err := GetObfs("auth_chain_" + tc.Mode)
		if err != nil {
			t.Fatal(err)
		}
		a := p.(*AuthChainA)
		key, err := hex.DecodeString(tc.Key)
		if err != nil {
			t.Fatal(err)
		}
		a.keyChangeDatetimeKey = tc.TimeBucket
		a.initDataSize(key)
		got := [][]int{a.DataSizeList0}
		if tc.Mode == "b" {
			got = [][]int{a.DataSizeList, a.DataSizeList2}
		}
		if !reflect.DeepEqual(got, tc.Lists) {
			t.Errorf("chain %s table: got %v want %v", tc.Mode, got, tc.Lists)
		}
	}
}
